<?php $q=trim($_GET['q']??'');$candidates=[['name'=>'Mira Shah','title'=>'Frontend Developer','location'=>'Ahmedabad, Gujarat','experience'=>'2 years','skills'=>['JavaScript','React','CSS'],'initial'=>'M','color'=>'violet'],['name'=>'Dev Patel','title'=>'PHP Developer','location'=>'Gandhinagar, Gujarat','experience'=>'1 year','skills'=>['PHP','MySQL','REST APIs'],'initial'=>'D','color'=>'blue'],['name'=>'Aanya Desai','title'=>'UI/UX Designer','location'=>'Remote, India','experience'=>'3 years','skills'=>['Figma','Research','Prototyping'],'initial'=>'A','color'=>'orange'],['name'=>'Rohan Mehta','title'=>'Data Analyst','location'=>'Ahmedabad, Gujarat','experience'=>'2 years','skills'=>['SQL','Python','Power BI'],'initial'=>'R','color'=>'green']];$results=array_values(array_filter($candidates,fn($c)=>!$q||str_contains(strtolower(implode(' ',$c)),strtolower($q)))); ?><div class="page-container"><div class="page-heading"><div><span class="eyebrow eyebrow-dark">MEET YOUR NEXT TEAMMATE</span><h1>Find the right <span>talent.</span></h1><p class="muted">Explore sample candidate profiles by role, location, or skill.</p></div></div><form method="get" class="search-panel candidate-search"><input type="hidden" name="page" value="search-candidates"><label class="search-field"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Search by role, skill, or location"></label><button class="btn btn-dark" type="submit">Search talent</button></form><div class="results-heading"><span><strong><?=count($results)?></strong> sample profiles</span><span class="demo-label">DEMO DATA</span></div><?php if($results):?><div class="candidate-grid"><?php foreach($results as $c):?><article class="candidate-card"><div class="candidate-top"><div class="candidate-avatar logo-<?=e($c['color'])?>"><?=e($c['initial'])?></div><span class="available-pill"><i></i> Open to opportunities</span></div><h3><?=e($c['name'])?></h3><p class="candidate-title"><?=e($c['title'])?></p><div class="candidate-meta"><span>⌖ <?=e($c['location'])?></span><span>◷ <?=e($c['experience'])?> experience</span></div><div class="skill-list"><?php foreach($c['skills'] as $s):?><span><?=e($s)?></span><?php endforeach;?></div><button class="btn btn-outline-dark btn-full" type="button" data-contact-candidate="<?=e($c['name'])?>">View contact options ↗</button></article><?php endforeach;?></div><?php else:?><div class="empty-state"><h3>No matching profiles</h3><p>Try a different keyword.</p><a class="btn btn-outline-dark" href="<?=url('search-candidates')?>">Clear search</a></div><?php endif;?></div><dialog id="candidateDialog" class="modal"><div class="modal-head"><h3 id="candidateDialogTitle">Candidate profile</h3><button type="button" class="modal-close" data-close-dialog>×</button></div><p>This demo uses sample candidate data. Real contact details and private resumes are not available.</p><button type="button" class="btn btn-dark" data-close-dialog>Close</button></dialog>